let fxl = {

    laserUnit: {
        mba: 5,         // cm Messbereichsanfang
        mb: 10,         // cm Messbereich
        mbe: 15,        // cm Messbereichsende
        ampRange: 16
    },

    driveUnit: {
        mode: 'AM8111',                                             // AM8111, ED1F
        gearBoxGearRatio: 1000.0,
        spindlePitch: 5.0,
        timingBeltTransmissionGearRatio: 2.0,
        motorIncrementPositions: 262144,                            // AM8111: 262144; ED1F: 8388608
        cylinderDiameter: 15.0,
        cylinderVolume: 10.0
    },

    position: {

        limit: {
            max: 13.11,     // cm top
            min: 8.13,      // cm bottom
            dev: 0.050
        },

        unit: "cm",
        digits: 3,

        valid: function (value, direction) {
            if (direction == -1 && value < this.limit.min - this.limit.dev)
                return false;
            if (direction == 1 && value > this.limit.max + this.limit.dev)
                return false;
            return true;
        }
    },

    volume: {
        limit: {
            min: 0.0,   // top (~0ml)
            max: 9.0    // bottom (~0ml+9ml) 
        },
        unit: "ml",
        digits: 6,
        valid: function (value) {
            return value >= this.limit.min && value <= this.limit.max;
        }
    },

    speed: {
        unit: "µl/min",
        digits: 3
    },

    cylinderArea: function() {
        return this.driveUnit.cylinderDiameter ** 2 * Math.PI / 4.
    },

    amp2cm: function (value) {
        return this.laserUnit.mba + this.laserUnit.mb * value / this.laserUnit.ampRange;
    },

    amp2ml: function (value) {
        return this.volume.limit.min + (this.position.limit.max - this.amp2cm(value)) * this.cylinderArea() / 100.0;
    },

    incs2mulmin: function (value) {
        // mm/r
        let transmission = this.driveUnit.spindlePitch / (this.driveUnit.timingBeltTransmissionGearRatio * this.driveUnit.gearBoxGearRatio);
        // mm³/r ~ µl/r
        let injectionRateRotation = transmission * this.cylinderArea();
        // µl/inc
        let injectionRateIncrement = injectionRateRotation / this.driveUnit.motorIncrementPositions;
        return parseFloat(Number(value * injectionRateIncrement * 60.0).toFixed(6));
    },

    incs2nalmin: function (value) {
        return this.incs2mulmin(value) * 1000;
    },

    mulmin2incs: function (value) {
        // mm/r
        let transmission = this.driveUnit.spindlePitch / (this.driveUnit.timingBeltTransmissionGearRatio * this.driveUnit.gearBoxGearRatio);
        // µl/r
        let injectionRateRotation = transmission * this.cylinderArea();
        // µl/inc
        let injectionRateIncrement = injectionRateRotation / this.driveUnit.motorIncrementPositions;
        // µl/min
        return value / (injectionRateIncrement * 60);
    },

    nalmin2incs: function (value) {
        return this.mulmin2incs(value / 1000.0);
    },

    turn2ml: function (value) {
        let V = this.driveUnit.spindlePitch * this.cylinderArea();
        let ratio = this.driveUnit.timingBeltTransmissionGearRatio * this.driveUnit.gearBoxGearRatio;
        let mtb = value[0] * V / ratio;
        let stb = value[1] / 65535 * V / ratio;
        return (mtb + stb) / 1000;
    },

    ml2turn: function (value) {                                
        let V = this.driveUnit.spindlePitch * this.cylinderArea();
        let ratio = this.driveUnit.timingBeltTransmissionGearRatio * this.driveUnit.gearBoxGearRatio;        
        let mtb = Math.trunc(value / V * ratio * 1000);
        let stb = 65535 * (value - this.turn2ml([mtb, 0])) / V * ratio * 1000;
        return [
            parseInt(Number(mtb).toFixed(0)), 
            parseInt(Number(stb).toFixed(0))
            ];
    },

    severity2string: function (value, sep=" ") {

        let severity = value.slice(0, 4);
        let reason = value.slice(4, 8);

        let ignore = parseInt(reason, 2) & 1;

        severity = parseInt(severity, 2);
        reason = parseInt(reason, 2) & ~1;

        let payload = [];

        let severities = ['INFORMATION', 'WARNING', 'ERROR', 'CRITICAL'];
        ['1000', '0100', '0010', '0001'].forEach(function (s, i) {
            let a = parseInt(s, 2);
            let b = severity;
            if (a == b) {
                payload.push(severities[i]);
            }
        });

        let reasons = ['TEMPERATURE', 'LOCK', 'PRESSURE', 'TIME', 'DISTANCE', 'SYSTEM'];

        ['1100', '1010', '1000', '0110', '0100', '0010'].forEach(function (r, i) {
            let a = parseInt(r, 2)
            let b = reason;
            if (a == b) {
                payload.push(reasons[i]);
            }
        });

        if (ignore) {
            payload.push("IGNORE");
        }

        if (payload.length == 0) {
            payload.push("NONE");
        }

        return payload.join(sep).toLowerCase();

    },

    profile: {

        value: function(value, range) {
            return value < 0 ? Math.pow(2, range) - 1 + value : value;
        },

        merge: function(value, bits, range = 32) {
            return this.value(parseInt(
                value[0].toString(2).padStart(bits, '0') +
                value[1].toString(2).padStart(range - bits, '0'), 2)
            );
        },

        split: function(value, bits, range = 32) {
            value = value.toString(2).padStart(range, '0');
            return [parseInt(value.slice(0, bits), 2), parseInt(value.slice(bits), 2)];
        }

    }

}

